"use client"

import { useEffect, useState } from "react"
import {
  collection,
  query,
  where,
  orderBy,
  onSnapshot,
  type QueryConstraint,
} from "firebase/firestore"
import { db } from "@/lib/firebase"
import { useUser } from "@/components/UserProvider"
import { heistConverter, type Heist } from "@/types/firestore/heist"

export type HeistFilter = "active" | "assigned" | "expired"

interface UseHeistsResult {
  heists: Heist[]
  loading: boolean
  error: Error | null
}

function buildConstraints(filter: HeistFilter, uid: string): QueryConstraint[] {
  const now = new Date()

  switch (filter) {
    case "active":
      return [
        where("assignedTo", "==", uid),
        where("deadline", ">", now),
        orderBy("deadline", "asc"),
      ]
    case "assigned":
      return [
        where("createdBy", "==", uid),
        where("deadline", ">", now),
        orderBy("deadline", "asc"),
      ]
    case "expired":
      return [
        where("finalStatus", "!=", null),
        where("deadline", "<", now),
        orderBy("finalStatus"),
        orderBy("deadline", "desc"),
      ]
  }
}

export function useHeists(filter: HeistFilter): UseHeistsResult {
  const { user } = useUser()
  const uid = user?.uid

  const [heists, setHeists] = useState<Heist[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<Error | null>(null)

  useEffect(() => {
    if (!uid) {
      setHeists([])
      setLoading(false)
      return
    }

    setLoading(true)
    setError(null)

    const ref = collection(db, "heists").withConverter(heistConverter)
    const q = query(ref, ...buildConstraints(filter, uid))

    const unsubscribe = onSnapshot(
      q,
      (snapshot) => {
        setHeists(snapshot.docs.map((doc) => doc.data()))
        setLoading(false)
      },
      (err) => {
        setError(err)
        setLoading(false)
      }
    )

    return unsubscribe
  }, [filter, uid])

  return { heists, loading, error }
}

