"use client"

import { useState } from "react"
import Link from "next/link"
import { useRouter } from "next/navigation"
import { Eye, EyeOff } from "lucide-react"
import styles from "./AuthForm.module.css"
import { signup } from "@/lib/auth/signup"
import { login } from "@/lib/auth/login"
import { logLoginAttempt } from "@/app/actions/logLoginAttempt"

interface AuthFormProps {
  mode: "login" | "signup"
}

function humanReadableError(err: unknown): string {
  const code = (err as { code?: string }).code
  if (code === "auth/email-already-in-use") return "An account with this email already exists."
  if (code === "auth/weak-password") return "Password must be at least 6 characters."
  if (code === "auth/invalid-email") return "Please enter a valid email address."
  if (code === "auth/invalid-login-credentials") return "Incorrect email or password."
  if (code === "auth/wrong-password") return "Incorrect email or password."
  if (code === "auth/user-not-found") return "No account found with that email."
  if (code === "auth/too-many-requests") return "Too many attempts. Please try again later."
  return "Something went wrong. Please try again."
}

export default function AuthForm({ mode }: AuthFormProps) {
  const router = useRouter()
  const [email, setEmail] = useState("")
  const [password, setPassword] = useState("")
  const [showPassword, setShowPassword] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [loading, setLoading] = useState(false)
  const [success, setSuccess] = useState(false)
  const [successName, setSuccessName] = useState("")

  const isLogin = mode === "login"
  const heading = isLogin ? "Log in to Your Account" : "Signup for an Account"
  const submitLabel = isLogin ? "Log In" : "Sign Up"
  const switchText = isLogin ? "Don't have an account? Sign up" : "Already have an account? Log in"
  const switchHref = isLogin ? "/signup" : "/login"

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    if (mode === "signup") {
      setLoading(true)
      setError(null)
      try {
        await signup(email, password)
        router.push("/heists")
      } catch (err) {
        setError(humanReadableError(err))
      } finally {
        setLoading(false)
      }
    } else {
      setLoading(true)
      setError(null)
      try {
        const displayName = await login(email, password)
        setSuccessName(displayName)
        setSuccess(true)
      } catch (err) {
        setError(humanReadableError(err))
      } finally {
        setLoading(false)
      }
    }
  }

  return (
    <div className={styles.authForm}>
      <h1 className="form-title">{heading}</h1>
      <form onSubmit={handleSubmit}>
        <div className={styles.field}>
          <label htmlFor="email">Email</label>
          <input
            id="email"
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            autoComplete="email"
          />
        </div>
        <div className={styles.field}>
          <label htmlFor="password">Password</label>
          <div className={styles.passwordWrapper}>
            <input
              id="password"
              type={showPassword ? "text" : "password"}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              autoComplete={isLogin ? "current-password" : "new-password"}
            />
            <button
              type="button"
              className={styles.toggleBtn}
              aria-label={showPassword ? "Hide password" : "Show password"}
              onClick={() => setShowPassword((v) => !v)}
            >
              {showPassword
                ? <EyeOff size={18} strokeWidth={2} />
                : <Eye size={18} strokeWidth={2} />
              }
            </button>
          </div>
        </div>
        {error && <p role="alert" className={styles.errorMsg}>{error}</p>}
        {success ? (
          <p role="status" className={styles.successMsg}>Welcome, {successName}.</p>
        ) : (
          <button type="submit" className={`btn ${styles.submitBtn}`} disabled={loading}>
            {loading ? (mode === "signup" ? "Signing up…" : "Logging in…") : submitLabel}
          </button>
        )}
      </form>
      <Link href={switchHref} className={styles.switchLink}>
        {switchText}
      </Link>
    </div>
  )
}

import { render, screen, waitFor } from "@testing-library/react"
import userEvent from "@testing-library/user-event"
import { describe, it, expect } from "vitest"
import AuthForm from "@/components/AuthForm"

const { mockLogin } = vi.hoisted(() => ({ mockLogin: vi.fn() }))
vi.mock("@/lib/auth/login", () => ({ login: mockLogin }))
vi.mock("next/navigation", () => ({ useRouter: () => ({ push: vi.fn() }) }))
vi.mock("@/lib/firebase", () => ({ auth: {} }))
vi.mock("firebase/auth", () => ({ getAuth: vi.fn(() => ({})) }))

beforeEach(() => vi.clearAllMocks())

async function fillAndSubmit(email = "agent@heist.com", password = "password123") {
  await userEvent.type(screen.getByLabelText("Email"), email)
  await userEvent.type(screen.getByLabelText("Password"), password)
  await userEvent.click(screen.getByRole("button", { name: /log in/i }))
}

describe("AuthForm (login mode)", () => {
  it("renders email and password fields", () => {
    render(<AuthForm mode="login" />)
    expect(screen.getByLabelText("Email")).toBeInTheDocument()
    expect(screen.getByLabelText("Password")).toBeInTheDocument()
  })

  it("disables the button and shows 'Logging in…' while pending", async () => {
    let resolve: (v: string) => void
    mockLogin.mockReturnValue(new Promise<string>((r) => { resolve = r }))
    render(<AuthForm mode="login" />)
    await fillAndSubmit()
    const btn = screen.getByRole("button", { name: /logging in/i })
    expect(btn).toBeDisabled()
    resolve!("GhostFox")
  })

  it("replaces the form with a success message on successful login", async () => {
    mockLogin.mockResolvedValue("GhostFox")
    render(<AuthForm mode="login" />)
    await fillAndSubmit()
    await waitFor(() =>
      expect(screen.getByRole("status")).toHaveTextContent("Welcome, GhostFox.")
    )
    expect(screen.queryByRole("button", { name: /log in/i })).not.toBeInTheDocument()
  })

  it("shows a human-readable error for a known Firebase error code", async () => {
    mockLogin.mockRejectedValue({ code: "auth/invalid-login-credentials" })
    render(<AuthForm mode="login" />)
    await fillAndSubmit()
    await waitFor(() =>
      expect(screen.getByRole("alert")).toHaveTextContent("Incorrect email or password.")
    )
  })

  it("shows a generic error for an unknown Firebase error code", async () => {
    mockLogin.mockRejectedValue({ code: "auth/unknown-code" })
    render(<AuthForm mode="login" />)
    await fillAndSubmit()
    await waitFor(() =>
      expect(screen.getByRole("alert")).toHaveTextContent("Something went wrong. Please try again.")
    )
  })
})

